import{_ as t,c as a,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Hydration","description":"Understand dough hydration and how water percentage affects texture, extensibility, and crust in bread baking.","frontmatter":{"title":"Hydration","description":"Understand dough hydration and how water percentage affects texture, extensibility, and crust in bread baking.","head":[["meta",{"name":"description","content":"Understand dough hydration and how water percentage affects texture, extensibility, and crust in bread baking."}],["meta",{"property":"og:title","content":"Hydration"}],["meta",{"property":"og:description","content":"Understand dough hydration and how water percentage affects texture, extensibility, and crust in bread baking."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/hydration.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Hydration"}],["meta",{"name":"twitter:description","content":"Understand dough hydration and how water percentage affects texture, extensibility, and crust in bread baking."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/hydration.html"}]]},"headers":[],"relativePath":"guides/hydration.md","filePath":"guides/hydration.md"}'),n={name:"guides/hydration.md"};function o(l,e,s,h,d,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="dough-hydration" tabindex="-1">Dough Hydration <a class="header-anchor" href="#dough-hydration" aria-label="Permalink to “Dough Hydration”">​</a></h1><p>Hydration is baker&#39;s shorthand for how wet a dough will feel. Flour is the baseline, water is the throttle.<br> No water, no bread. Higher number, looser dough. Lower number, stiffer dough.</p><p><strong>Hydration % = (Liquid Water ÷ Total Flour) × 100</strong></p><h2 id="hydration-vs-effective-hydration" tabindex="-1">Hydration vs. Effective Hydration <a class="header-anchor" href="#hydration-vs-effective-hydration" aria-label="Permalink to “Hydration vs. Effective Hydration”">​</a></h2><p>There are no hard rules, but this is the practical split that works in the real world.</p><ul><li><strong>Hydration (liquids):</strong> the water you pour in, plus watery liquids like milk, cream, buttermilk, coffee, tea, beer, wine, juice, kombucha, etc.</li><li><strong>Effective hydration:</strong> total water from every ingredient, including eggs, butter, sugars, and yeast water where applicable.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Butter and eggs usually do not count toward base hydration, but they absolutely change how a dough feels.</p></div><h2 id="adjusted-effective-hydration" tabindex="-1">Adjusted Effective Hydration <a class="header-anchor" href="#adjusted-effective-hydration" aria-label="Permalink to “Adjusted Effective Hydration”">​</a></h2><p>This is the new reality-check number. It starts with effective hydration, then adjusts for starch-heavy ingredients that soak up water and quietly change dough behavior.</p><ul><li><strong>Adjusted effective hydration:</strong> effective hydration corrected for how much water starches bind in the final mix.</li></ul><p>Think of it as your &quot;what the dough actually feels like&quot; hydration after the thirsty ingredients have had their turn at the bowl.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Bread flour does pull in a little extra water, but usually not enough to cause drama by itself. Potatoes and rye are different animals: they can hold a lot more water, and if you ignore that, dough can feel tighter, ferment differently, and bake up denser than expected.</p></div><h2 id="why-the-calculator-shows-all-three" tabindex="-1">Why the Calculator Shows All Three <a class="header-anchor" href="#why-the-calculator-shows-all-three" aria-label="Permalink to “Why the Calculator Shows All Three”">​</a></h2><p>Three numbers, three jobs. Think of them as your mix control, moisture truth, and starch-corrected reality check.</p><ul><li><strong>Hydration (liquids)</strong> is the handling knob. It tells you how slack the dough will be when you mix.</li><li><strong>Effective hydration</strong> is the moisture truth. It explains why enriched doughs can feel &quot;wetter&quot; than the base hydration suggests.</li><li><strong>Adjusted effective hydration</strong> is the practical behavior number. It helps explain why starch-heavy formulas can still feel drier than their raw moisture numbers suggest.</li></ul><div class="info custom-block"><p class="custom-block-title">Why this works</p><p>One number helps you tune handling, one explains total moisture, and one accounts for starch absorption. Together they make hydration easier to predict, not harder.</p></div><h2 id="hydration-levels" tabindex="-1">Hydration Levels <a class="header-anchor" href="#hydration-levels" aria-label="Permalink to “Hydration Levels”">​</a></h2><h3 id="low-hydration-60" tabindex="-1"><strong>Low Hydration (&lt; 60%)</strong> <a class="header-anchor" href="#low-hydration-60" aria-label="Permalink to “Low Hydration (&lt; 60%)”">​</a></h3><ul><li>Firm, stiff dough</li><li>Easy to shape</li><li>Tight crumb (bagels, pretzels, sandwich loaves)</li></ul><h3 id="medium-hydration-60-70" tabindex="-1"><strong>Medium Hydration (60-70%)</strong> <a class="header-anchor" href="#medium-hydration-60-70" aria-label="Permalink to “Medium Hydration (60-70%)”">​</a></h3><ul><li>Soft, workable dough</li><li>Balanced crumb</li><li>Great all-purpose range for beginners</li></ul><h3 id="high-hydration-70" tabindex="-1"><strong>High Hydration (&gt; 70%)</strong> <a class="header-anchor" href="#high-hydration-70" aria-label="Permalink to “High Hydration (&gt; 70%)”">​</a></h3><ul><li>Wet, sticky dough</li><li>Open, airy crumb</li><li>Harder to handle</li><li><strong>Tip:</strong> Use gentle folding during bulk fermentation to build strength - especially for no-knead doughs.</li></ul><h2 id="why-hydration-matters" tabindex="-1">Why Hydration Matters <a class="header-anchor" href="#why-hydration-matters" aria-label="Permalink to “Why Hydration Matters”">​</a></h2><p>Water drives the whole show: fermentation, gluten development, starch hydration, and the final texture and keeping quality.</p><p>Hydration influences:</p><ul><li>Mixing difficulty</li><li>Dough strength</li><li>Extensibility (how far the dough can stretch)</li><li>Crumb openness</li><li>Crust thickness</li></ul><p>Once you know hydration, you can compare recipes clearly and predict how a dough will feel before you start mixing.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p><strong>Recipe:</strong></p><ul><li>Flour: 1000g</li><li>Water: 600g</li><li>Eggs: 150g (~113g water)</li><li>Butter: 100g (~18g water)</li></ul><p><strong>Hydration (liquids):</strong> 600 ÷ 1000 = <strong>60%</strong><br><strong>Effective hydration:</strong> (600 + 113 + 18) ÷ 1000 = <strong>73%</strong></p><p>This dough shows a low base hydration but still feels soft because of eggs and butter.</p><p>Understanding effective hydration and adjusted effective hydration helps you scale recipes, adjust ingredients, and troubleshoot dough with much better accuracy - especially for enriched or starch-heavy breads.</p><p>Experiment with different hydration levels to find what works best for your baking style and the breads you love!</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li><li><a href="/ingredients/water.html">Water</a></li><li><a href="/ingredients/flour.html">Flour</a></li></ul>',37)])])}const y=t(n,[["render",o]]);export{g as __pageData,y as default};
